#!/usr/bin/env bash
#
# Resume a pipeline script generated by an OLD gen_hefesto_resample_pipeline.py
# (before be8f931), whose only stages are stage0..stage4 -- stage1/stage2 each
# build, run AND import in one function, and both start with rm -rf of their
# tree. This resumes partway through those stages without rebuilding the tree.
#
# It sources the old script's CONFIG block + helper/stage functions (everything
# above its DISPATCH marker), lifts the "stage Nc" import commands out of the
# old stage1()/stage2() verbatim (so any --verify / --import-args flags are
# kept), and runs:
#   stage1b : run HeFESTo on RS1, 1c, old stage2 (full: rebuild RS2), 3, 4
#   stage1c : 1c, old stage2 (full), 3, 4
#   stage2b : run HeFESTo on RS2, 2c, 3, 4
#   stage2c : 2c, 3, 4
#
# Before 1b/2b it checks the tree for top-level directories that are listed in
# submitted_jobs.log but still have Simulation dirs with no output (e.g. jobs
# killed by a cluster reset) -- the submitter would otherwise skip them. It
# aborts if it finds any, unless you pass:
#   --prune  remove those directories from submitted_jobs.log (backup kept as
#            submitted_jobs.log.bak.<timestamp>) so they are resubmitted
#   --force  resume anyway, leaving them skipped
#
# PREREQUISITE: HeFESTo env active in this shell, as for the old script itself.
#
# USAGE:  bash resume_old_pipeline.sh OLD_PIPELINE_SCRIPT STAGE [--prune|--force]
#   e.g.  bash resume_old_pipeline.sh \
#           /resnick/.../CMBPipeline/run_CMB_pipeline.sh stage2b --prune

set -euo pipefail

usage() { sed -n '2,/^$/s/^# \{0,1\}//p' "$0" >&2; exit "${1:-1}"; }

[ $# -ge 2 ] || usage
OLD="$1"; START="$2"; MODE="${3:-check}"
case "$MODE" in check|--prune|--force) ;; *) usage ;; esac
case "$START" in stage1b|stage1c|stage2b|stage2c) ;; *)
  echo "ERROR: STAGE must be one of stage1b stage1c stage2b stage2c" >&2; exit 1 ;;
esac
[ -f "$OLD" ] || { echo "ERROR: no such script: $OLD" >&2; exit 1; }
grep -q '^stage2()' "$OLD" || {
  echo "ERROR: $OLD has no stage2() -- it is a new-style script; run it directly:" >&2
  echo "  bash $OLD $START" >&2; exit 1; }
grep -q '^# -* DISPATCH' "$OLD" || {
  echo "ERROR: no DISPATCH marker in $OLD (too old to source safely)" >&2; exit 1; }

# Print the "stage Nc" section of old function stageN() (banner line through
# the end of the function body).
extract_c() {
  awk -v fn="$1()" -v tag="banner \"stage ${1#stage}c " '
    index($0, fn " {") == 1 { inf = 1; next }
    inf && /^}/             { inf = 0 }
    inf && index($0, tag)   { on = 1 }
    inf && on               { print }' "$OLD"
}

# CONFIG + helpers + old stage functions, without running the old dispatcher
# shellcheck disable=SC1090
source <(sed '/^# -* DISPATCH/,$d' "$OLD")

for n in 1 2; do
  body=$(extract_c "stage$n")
  [ -n "$body" ] || { echo "ERROR: could not find stage ${n}c in $OLD" >&2; exit 1; }
  eval "stage${n}c() {
$body
}"
done

# Top-level dirs of $1 that are in submitted_jobs.log but have unrun sims.
incomplete_submitted() {
  "$PYTHON" - "$1" <<'PY'
import os, re, sys
base = sys.argv[1]
log = os.path.join(base, 'submitted_jobs.log')
if not os.path.isfile(log):
    sys.exit(0)
logged = {l.split('  job=')[0].strip() for l in open(log) if '  job=' in l}
pat = re.compile(r'^Simulation\d+$', re.I)
for d in sorted(logged):
    p = os.path.join(base, d)
    if not os.path.isdir(p):
        continue
    for s in os.listdir(p):
        sp = os.path.join(p, s)
        if pat.match(s) and os.path.isdir(sp) and \
                not (set(os.listdir(sp)) - {'control', 'ad.in'}):
            print(d)
            break
PY
}

check_tree() {
  local tree="$1" bad n
  bad=$(incomplete_submitted "$tree")
  n=$(printf '%s' "$bad" | grep -c . || true)
  if [ "$n" -eq 0 ]; then
    echo "[check] $tree: every submitted directory has full output"
    return
  fi
  echo "[check] $tree: $n submitted director(y/ies) with unrun simulations:"
  printf '  %s\n' $bad
  case "$MODE" in
    --prune)
      local log="$tree/submitted_jobs.log" bak
      bak="$log.bak.$(date +%Y%m%d_%H%M%S)"
      cp "$log" "$bak"
      awk 'NR==FNR { bad[$1] = 1; next } !($1 in bad)' \
          <(printf '%s\n' $bad) "$bak" > "$log"
      echo "[check] pruned them from $log (backup: $bak) -> will be resubmitted" ;;
    --force)
      echo "[check] --force: leaving them skipped" ;;
    *)
      echo "ERROR: re-run with --prune to resubmit them, or --force to skip them" >&2
      exit 1 ;;
  esac
}

case "$START" in
  stage1b) check_tree "$RS1"
           banner "stage 1b -- run HeFESTo on RS1 (resume)"
           run_hefesto_tree "$RS1"
           stage1c; stage2; stage3; stage4 ;;
  stage1c) stage1c; stage2; stage3; stage4 ;;
  stage2b) check_tree "$RS2"
           banner "stage 2b -- run HeFESTo on RS2 (resume)"
           run_hefesto_tree "$RS2"
           stage2c; stage3; stage4 ;;
  stage2c) stage2c; stage3; stage4 ;;
esac
